<script>
  import { bus } from "../../../event-bus";
  export default {
    props:['url','name','mode'],
    data () {
      return {
        medical:[],
        profile_tab:'',
        errors:[],
        success:null,     
      }
    },
    computed: {
      hasMedicalContent() {
        if (!this.medical || typeof this.medical !== 'object') {
          return false;
        }

        return [
          'medication_problems',
          'medication_needs',
          'medication_allergies',
          'food_allergies',
          'other_allergies',
          'other_medical_information',
        ].some((key) => {
          const value = this.medical[key];
          return value != null && String(value).trim() !== '';
        });
      },
    },
    methods:
    {
      getData()
      {
        axios.get('/'+this.mode+'/student/show/medicalHistory/'+this.name).then(response => {
          this.medical = response.data;
        });
      },
    },
  
    created()
    {    
      this.getData();
      bus.$on("dataProfileTab", data => {
        if(data!='')
        {
          this.profile_tab=data;                   
        }
      });      
    }
  }
</script>